package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Adds opening balances per pasted line of name,period,amount, in order: the person on the sheet by name or alias,
 * the period on the sheet by name, and an amount of two decimals, 0.00 or more, added to the person's opening balance
 * for the period and so to their carried figure for it. Every line is checked first; if any is refused, nothing is
 * added.
 */
@Service
public class OpeningImportService {

    private static final String AMOUNT = "\\d{1,12}\\.\\d{2}";

    private record Line(int number, Person person, Period period, BigDecimal amount) {
    }

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final PersonService people;
    private final Audit audit;

    public OpeningImportService(PeriodRepository periods, SheetRepository sheets, PersonService people, Audit audit) {
        this.periods = periods;
        this.sheets = sheets;
        this.people = people;
        this.audit = audit;
    }

    /** How many lines were added. */
    @Transactional
    public int importOpenings(String sheetId, String user, String text) {
        // Lock the sheet so no period closes while the openings are added.
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        List<Line> lines = new ArrayList<>();
        String[] rows = text.split("\\r?\\n");
        for (int i = 0; i < rows.length; i++) {
            if (!rows[i].isBlank()) {
                lines.add(parse(sheetId, i + 1, rows[i]));
            }
        }
        if (lines.isEmpty()) {
            throw new OpeningImportException("Paste at least one line of name,period,amount");
        }
        for (Line line : lines) {
            Period period = line.period();
            period.addOpening(line.person().getId(), line.amount());
            periods.save(period);
            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
                    + " period=" + period.getName() + " amount=" + line.amount().toPlainString());
        }
        periods.flush();
        return lines.size();
    }

    private Line parse(String sheetId, int number, String row) {
        String[] fields = row.split(",", -1);
        if (fields.length != 3) {
            throw new OpeningImportException(number, "expected name,period,amount");
        }
        String name = fields[0].trim();
        if (name.isEmpty()) {
            throw new OpeningImportException(number, "the name is blank");
        }
        Person person = people.findByNameOrAlias(sheetId, name)
                .orElseThrow(() -> new OpeningImportException(number, "no one on the sheet is named " + name));
        String periodName = fields[1].trim();
        Period period = periods.findBySheetIdAndName(sheetId, periodName)
                .orElseThrow(() -> new OpeningImportException(number, "the sheet has no period " + periodName));
        String amount = fields[2].trim();
        if (!amount.matches(AMOUNT)) {
            throw new OpeningImportException(number, "the amount is not 0.00 or more with two decimals");
        }
        return new Line(number, person, period, new BigDecimal(amount));
    }
}

    /**
     * Each person's due-total of the dates from and to, both inclusive, by person id for every person on the sheet, as
     * the screen shows a person's for a period: the dues as shown now of their claims due by a date in them that were OPEN,
     * PENDING or SETTLED at the end of the to-date by their status log, skipping those with no due and the open ones
     * their retirement leaves out; 0.00 with none.
     */
    public Map<Long, BigDecimal> dueTotalsBetween(String sheetId, LocalDate from, LocalDate to) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        List<List<Rate>> sheetRates = rateChain(sheetId);
        Map<Long, Person> byId = new LinkedHashMap<>();
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            byId.put(person.getId(), person);
            totals.put(person.getId(), zero());
        }
        Map<Long, List<ClaimLog>> logOf = new LinkedHashMap<>();
        for (ClaimLog line : logs.findBySheetIdOrderByIdAsc(sheetId)) {
            logOf.computeIfAbsent(line.getClaimId(), id -> new ArrayList<>()).add(line);
        }
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            ClaimStatus status = statusOn(claim, logOf.getOrDefault(claim.getId(), List.of()), to);
            if (person == null || !person.countsAsOf(claim, status, today) || claim.getDueBy().isBefore(from)
                    || claim.getDueBy().isAfter(to)) {
                continue;
            }
            dueOf(sheet, sheetRates, person, claim).ifPresent(due -> totals.merge(person.getId(), due, BigDecimal::add));
        }
        totals.replaceAll((id, total) -> total.setScale(2, RoundingMode.HALF_EVEN));
        return totals;
    }

    /**
     * Each person's carried figure for the period, by person id for every person on the sheet, as the screen shows it
     * while the period is open: the dues as shown now of their claims due by a date in one of the periods that ends
     * before it starts that were OPEN or PENDING at the end of its to-date by their status log and count then, skipping
     * those with no due, plus their opening balance for it; 0.00 with none.
     */
    public Map<Long, BigDecimal> carriedInto(String sheetId, List<Period> periods, Period period) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        List<List<Rate>> sheetRates = rateChain(sheetId);
        Map<Long, Person> byId = new LinkedHashMap<>();
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
            byId.put(person.getId(), person);
            totals.put(person.getId(), zero());
        }
        Map<Long, List<ClaimLog>> logOf = new LinkedHashMap<>();
        for (ClaimLog line : logs.findBySheetIdOrderByIdAsc(sheetId)) {
            logOf.computeIfAbsent(line.getClaimId(), id -> new ArrayList<>()).add(line);
        }
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || claim.getDueBy() == null) {
                continue;
            }
            Optional<Period> from = periods.stream().filter(p -> p.contains(claim.getDueBy())).findFirst();
            if (from.isEmpty() || !from.get().getToDate().isBefore(period.getFromDate())) {
                continue;
            }
            ClaimStatus status = statusOn(claim, logOf.getOrDefault(claim.getId(), List.of()), period.getToDate());
            if (status == null || !status.isOpen() || !person.countsAsOf(claim, status, today)) {
                continue;
            }
            dueOf(sheet, sheetRates, person, claim).ifPresent(due -> totals.merge(person.getId(), due, BigDecimal::add));
        }
        period.getPersonOpenings().forEach((id, opening) -> totals.computeIfPresent(id, (k, total) -> total.add(opening)));
        totals.replaceAll((id, total) -> total.setScale(2, RoundingMode.HALF_EVEN));
        return totals;
    }

